				return { success: true, deletedCount: 0 };
			}

			// Get all questions and verify ownership
			const questionsWithSurvey = await db
				.select({
					questionId: question.id,
					surveyOwnerId: survey.ownerId,
				})
				.from(question)
				.innerJoin(survey, eq(question.surveyId, survey.id))
				.where(inArray(question.id, input.ids));

			const ownedIds = questionsWithSurvey
				.filter((q) => q.surveyOwnerId === context.session.user.id)
				.map((q) => q.questionId);

			if (ownedIds.length === 0) {
				return { success: true, deletedCount: 0 };
			}

			await db.delete(question).where(inArray(question.id, ownedIds));

			return { success: true, deletedCount: ownedIds.length };
		}),
};
