const createLogicRuleSchema = z.object({
	surveyId: z.number().int(),
	sourceQuestionId: z.number().int(),
	targetQuestionId: z.number().int().optional(),
	operator: z.enum(logicOperators),
	value: z.union([
		z.string(),
		z.number(),
		z.boolean(),
		z.array(z.string()),
		z.null(),
	]),
	action: z.enum(logicActions),
	priority: z.number().int().default(0),
});

// Update logic rule input
const updateLogicRuleSchema = z.object({
	id: z.number().int(),
	sourceQuestionId: z.number().int().optional(),
	targetQuestionId: z.number().int().optional(),
	operator: z.enum(logicOperators).optional(),
	value: z.any().optional(),
	action: z.enum(logicActions).optional(),
	priority: z.number().int().optional(),
});

// Helper to verify survey ownership
async function verifySurveyOwnership(
	surveyId: number,
	userId: string,
): Promise<boolean> {
	const [result] = await db
		.select({ id: survey.id })
		.from(survey)
		.where(and(eq(survey.id, surveyId), eq(survey.ownerId, userId)));

	return !!result;
}

// Validate logic rule (no infinite loops, broken paths)
async function validateLogicRule(
	surveyId: number,
	ruleData: {
		id?: number;
		sourceQuestionId: number;
		targetQuestionId?: number;
		action: string;
	},
): Promise<{ valid: boolean; error?: string }> {
	// Get all questions for the survey
	const questions = await db
		.select()
		.from(question)
		.where(eq(question.surveyId, surveyId))
		.orderBy(question.order);

	const questionIds = new Set(questions.map((q) => q.id));

	// Validate source question exists
	if (!questionIds.has(ruleData.sourceQuestionId)) {
		return { valid: false, error: "Source question not found in survey" };
	}

	// Validate target question exists (if specified and action is jump_to)
	if (
		ruleData.action === "jump_to" &&
		ruleData.targetQuestionId &&
		!questionIds.has(ruleData.targetQuestionId)
	) {
		return { valid: false, error: "Target question not found in survey" };
	}

	// Get all existing logic rules for this survey
	const existingRules = await db
		.select()
		.from(logicRule)
		.where(eq(logicRule.surveyId, surveyId));

	// Check for infinite loops using graph traversal
	const visited = new Set<number>();
	const recursionStack = new Set<number>();

	function hasCycle(questionId: number, rules: typeof existingRules): boolean {
		visited.add(questionId);
		recursionStack.add(questionId);

		for (const rule of rules) {
			if (rule.sourceQuestionId === questionId && rule.targetQuestionId) {
				if (!visited.has(rule.targetQuestionId)) {
					if (hasCycle(rule.targetQuestionId, rules)) {
						return true;
					}
				} else if (recursionStack.has(rule.targetQuestionId)) {
					return true;
				}
			}
		}

		recursionStack.delete(questionId);
		return false;
	}

	// Build the rule set to validate
	const rulesToValidate = ruleData.id
		? existingRules.map((r) =>
				r.id === ruleData.id
					? { ...r, ...ruleData, targetQuestionId: ruleData.targetQuestionId ?? r.targetQuestionId }
					: r,
			)
		: [...existingRules, { ...ruleData, id: -1 }];

	// Check for cycles
	for (const q of questions) {
		if (!visited.has(q.id)) {
			if (hasCycle(q.id, rulesToValidate)) {
				return { valid: false, error: "Logic rule would create an infinite loop" };
			}
		}
	}

	return { valid: true };
}

