### 3. API Router Implementations

#### `/packages/api/src/routers/survey.ts`

```typescript
import { db } from "@orksys-survey/db";
import { survey, surveyStatus } from "@orksys-survey/db/schema/survey";
import { and, count, desc, eq, ilike, inArray, sql } from "drizzle-orm";
import z from "zod";

import { protectedProcedure, publicProcedure } from "../index";

// Pagination schema reused across list endpoints
const paginationSchema = z.object({
	page: z.number().int().min(1).default(1),
	limit: z.number().int().min(1).max(100).default(20),
});

// Survey filter schema
const surveyFilterSchema = z.object({
	status: z.enum(surveyStatus).optional(),
	search: z.string().optional(),
	organizationId: z.number().optional(),
});

// Create survey input
const createSurveySchema = z.object({
	title: z.string().min(1).max(255),
	description: z.string().optional(),
	slug: z.string().min(3).max(100).regex(/^[a-z0-9-]+$/),
	settings: z
		.object({
			anonymous: z.boolean().default(true),
			showProgressBar: z.boolean().default(true),
			brandingEnabled: z.boolean().default(false),
			primaryColor: z.string().optional(),
			logoUrl: z.string().url().optional(),
			thankYouMessage: z.string().optional(),
			requireAuth: z.boolean().default(false),
		})
		.optional(),
	organizationId: z.number().optional(),
});

// Update survey input
const updateSurveySchema = z.object({
	id: z.number().int(),
	title: z.string().min(1).max(255).optional(),
	description: z.string().optional(),
	settings: z.any().optional(),
});

// Change status input
const changeStatusSchema = z.object({
	id: z.number().int(),
	status: z.enum(surveyStatus),
});

export const surveyRouter = {
	// List all surveys for the authenticated user
	list: protectedProcedure
		.input(
			z.object({
				pagination: paginationSchema.optional(),
				filter: surveyFilterSchema.optional(),
			}),
		)
		.handler(async ({ context, input }) => {
			const { page = 1, limit = 20 } = input.pagination ?? {};
			const { status, search, organizationId } = input.filter ?? {};

			const conditions = [eq(survey.ownerId, context.session.user.id)];

			if (status) {
				conditions.push(eq(survey.status, status));
			}
			if (search) {
				conditions.push(ilike(survey.title, `%${search}%`));
			}
			if (organizationId) {
				conditions.push(eq(survey.organizationId, organizationId));
			}

			const [items, [{ total }]] = await Promise.all([
				db
					.select()
					.from(survey)
					.where(and(...conditions))
					.orderBy(desc(survey.updatedAt))
					.limit(limit)
					.offset((page - 1) * limit),
				db
					.select({ total: count() })
					.from(survey)
					.where(and(...conditions)),
			]);

			return {
				items,
				pagination: {
					page,
					limit,
					total,
					totalPages: Math.ceil(total / limit),
				},
			};
		}),

	// Get a single survey by ID (protected - owner only)
	getById: protectedProcedure
		.input(z.object({ id: z.number().int() }))
		.handler(async ({ context, input }) => {
			const [result] = await db
				.select()
				.from(survey)
				.where(
					and(eq(survey.id, input.id), eq(survey.ownerId, context.session.user.id)),
				);

			if (!result) {
				throw new Error("Survey not found");
			}

			return result;
		}),

	// Get a survey by slug (public - for survey runner)
	getBySlug: publicProcedure
		.input(z.object({ slug: z.string() }))
		.handler(async ({ input }) => {
			const [result] = await db
				.select()
				.from(survey)
				.where(eq(survey.slug, input.slug));

			if (!result) {
				throw new Error("Survey not found");
			}

			if (result.status !== "published") {
				throw new Error("Survey is not available");
			}

			return result;
		}),

	// Create a new survey
	create: protectedProcedure
		.input(createSurveySchema)
		.handler(async ({ context, input }) => {
			// Check slug uniqueness
			const [existing] = await db
				.select({ id: survey.id })
				.from(survey)
				.where(eq(survey.slug, input.slug))
				.limit(1);

			if (existing) {
				throw new Error("Slug already in use");
			}

			const [result] = await db
				.insert(survey)
				.values({
					...input,
					ownerId: context.session.user.id,
					settings: input.settings ?? {
						anonymous: true,
						showProgressBar: true,
						brandingEnabled: false,
						requireAuth: false,
					},
				})
				.returning();

			return result;
		}),

	// Update a survey
	update: protectedProcedure
		.input(updateSurveySchema)
		.handler(async ({ context, input }) => {
			const { id, ...data } = input;

			// Verify ownership
			const [existing] = await db
				.select({ ownerId: survey.ownerId })
				.from(survey)
				.where(eq(survey.id, id));

			if (!existing || existing.ownerId !== context.session.user.id) {
				throw new Error("Survey not found or access denied");
			}

			const [result] = await db
				.update(survey)
				.set(data)
				.where(eq(survey.id, id))
				.returning();

			return result;
		}),

	// Change survey status (draft -> published -> closed)
	changeStatus: protectedProcedure
		.input(changeStatusSchema)
		.handler(async ({ context, input }) => {
			const { id, status } = input;

			// Verify ownership
			const [existing] = await db
				.select({ ownerId: survey.ownerId, status: survey.status })
				.from(survey)
				.where(eq(survey.id, id));

			if (!existing || existing.ownerId !== context.session.user.id) {
				throw new Error("Survey not found or access denied");
			}

			const updateData: Record<string, unknown> = { status };

			if (status === "published" && existing.status !== "published") {
				updateData.publishedAt = new Date();
			}
			if (status === "closed" && existing.status !== "closed") {
				updateData.closedAt = new Date();
			}

			const [result] = await db
				.update(survey)
				.set(updateData)
				.where(eq(survey.id, id))
				.returning();

			return result;
		}),

	// Delete a survey
	delete: protectedProcedure
		.input(z.object({ id: z.number().int() }))
		.handler(async ({ context, input }) => {
			// Verify ownership
			const [existing] = await db
				.select({ ownerId: survey.ownerId })
				.from(survey)
				.where(eq(survey.id, input.id));

			if (!existing || existing.ownerId !== context.session.user.id) {
				throw new Error("Survey not found or access denied");
			}

			await db.delete(survey).where(eq(survey.id, input.id));

			return { success: true, id: input.id };
		}),

	// Bulk delete surveys
	bulkDelete: protectedProcedure
		.input(z.object({ ids: z.array(z.number().int()) }))
		.handler(async ({ context, input }) => {
			// Verify ownership of all surveys
			const surveys = await db
				.select({ id: survey.id })
				.from(survey)
				.where(
					and(
						inArray(survey.id, input.ids),
						eq(survey.ownerId, context.session.user.id),
					),
				);

			const ownedIds = surveys.map((s) => s.id);

			if (ownedIds.length === 0) {
				return { success: true, deletedCount: 0 };
			}

			await db.delete(survey).where(inArray(survey.id, ownedIds));

			return { success: true, deletedCount: ownedIds.length };
		}),
};
```

