	// Bulk create questions
	bulkCreate: protectedProcedure
		.input(bulkCreateSchema)
		.handler(async ({ context, input }) => {
			const hasAccess = await verifySurveyOwnership(
				input.surveyId,
				context.session.user.id,
			);
			if (!hasAccess) {
				throw new Error("Survey not found or access denied");
			}

			// Get current max order
			const [maxOrder] = await db
				.select({ max: sql<number>`COALESCE(MAX(${question.order}), -1)` })
				.from(question)
				.where(eq(question.surveyId, input.surveyId));

			let currentOrder = (maxOrder?.max ?? -1) + 1;

			const questionsToInsert = input.questions.map((q) => ({
				...q,
				surveyId: input.surveyId,
				order: currentOrder++,
			}));

			const results = await db
				.insert(question)
				.values(questionsToInsert)
				.returning();

			return results;
		}),

	// Bulk delete questions
	bulkDelete: protectedProcedure
		.input(z.object({ ids: z.array(z.number().int()) }))
		.handler(async ({ context, input }) => {
			if (input.ids.length === 0) {
				return { success: true, deletedCount: 0 };
			}

			// Get all questions and verify ownership
			const questionsWithSurvey = await db
				.select({
					questionId: question.id,
					surveyOwnerId: survey.ownerId,
				})
				.from(question)
				.innerJoin(survey, eq(question.surveyId, survey.id))
				.where(inArray(question.id, input.ids));

			const ownedIds = questionsWithSurvey
				.filter((q) => q.surveyOwnerId === context.session.user.id)
				.map((q) => q.questionId);

			if (ownedIds.length === 0) {
				return { success: true, deletedCount: 0 };
			}

			await db.delete(question).where(inArray(question.id, ownedIds));

			return { success: true, deletedCount: ownedIds.length };
		}),
};
