import { db } from "@orksys-survey/db";
import { answer } from "@orksys-survey/db/schema/answer";
import { question } from "@orksys-survey/db/schema/question";
import { response } from "@orksys-survey/db/schema/response";
import { survey } from "@orksys-survey/db/schema/survey";
import { and, count, desc, eq, inArray } from "drizzle-orm";
import { nanoid } from "nanoid";
import z from "zod";

import { protectedProcedure, publicProcedure } from "../index";

// Submit response input
const submitResponseSchema = z.object({
	surveySlug: z.string(),
	answers: z.array(
		z.object({
			questionId: z.number().int(),
			value: z.union([
				z.string(),
				z.number(),
				z.array(z.string()),
				z.boolean(),
				z.null(),
			]),
		}),
	),
	metadata: z
		.object({
			userAgent: z.string().optional(),
			deviceType: z.enum(["desktop", "mobile", "tablet"]).optional(),
			browser: z.string().optional(),
			os: z.string().optional(),
			language: z.string().optional(),
			referrer: z.string().optional(),
		})
		.optional(),
	anonymousFingerprint: z.string().max(64).optional(),
});

// Response filter schema
const responseFilterSchema = z.object({
	surveyId: z.number().int(),
	status: z.enum(["in_progress", "completed", "partial"]).optional(),
});

// Pagination schema
const paginationSchema = z.object({
	page: z.number().int().min(1).default(1),
	limit: z.number().int().min(1).max(100).default(20),
});

// Generate anonymous fingerprint (for preventing duplicate submissions)
function generateFingerprint(metadata: Record<string, unknown>): string {
	const data = JSON.stringify({
		userAgent: metadata.userAgent,
		deviceType: metadata.deviceType,
		language: metadata.language,
	});
	// In production, use a proper hash function
	return Buffer.from(data).toString("base64").slice(0, 64);
}

export const responseRouter = {
	// ============================================
	// PUBLIC ENDPOINTS (for survey runner)
	// ============================================

	// Get survey with questions for rendering (public)
	getSurveyForRunner: publicProcedure
		.input(z.object({ slug: z.string() }))
		.handler(async ({ input }) => {
			const [surveyResult] = await db
				.select()
				.from(survey)
				.where(eq(survey.slug, input.slug));

			if (!surveyResult) {
				throw new Error("Survey not found");
			}

			if (surveyResult.status !== "published") {
				throw new Error("Survey is not available");
			}

			const questions = await db
				.select()
				.from(question)
				.where(eq(question.surveyId, surveyResult.id))
				.orderBy(question.order);

			// Get logic rules for branching
			const logicRules = await db
				.select()
				.from(logicRule)
				.where(eq(logicRule.surveyId, surveyResult.id))
				.orderBy(logicRule.priority);

			return {
				survey: surveyResult,
				questions,
				logicRules,
			};
		}),

	// Submit a survey response (public)
	submit: publicProcedure
		.input(submitResponseSchema)
		.handler(async ({ context, input }) => {
			// Get survey
			const [surveyResult] = await db
				.select()
				.from(survey)
				.where(eq(survey.slug, input.surveySlug));

			if (!surveyResult) {
				throw new Error("Survey not found");
			}

			if (surveyResult.status !== "published") {
				throw new Error("Survey is not accepting responses");
			}

			// Check for anonymous fingerprint duplicate
			const settings = surveyResult.settings as { anonymous?: boolean } | null;
			if (settings?.anonymous && input.anonymousFingerprint) {
				const [existing] = await db
					.select({ id: response.id })
					.from(response)
					.where(
						and(
							eq(response.surveyId, surveyResult.id),
							eq(response.anonymousFingerprint, input.anonymousFingerprint),
							eq(response.status, "completed"),
						),
					)
					.limit(1);

				if (existing) {
					throw new Error("You have already submitted a response to this survey");
				}
			}

			// Validate required questions
			const questions = await db
				.select()
				.from(question)
				.where(eq(question.surveyId, surveyResult.id));

			const requiredQuestionIds = new Set(
				questions.filter((q) => q.required).map((q) => q.id),
			);
			const answeredQuestionIds = new Set(
				input.answers.map((a) => a.questionId),
			);

			for (const requiredId of requiredQuestionIds) {
				if (!answeredQuestionIds.has(requiredId)) {
					throw new Error("All required questions must be answered");
				}
			}

			// Create response with answers in a transaction
			const result = await db.transaction(async (tx) => {
				// Create response
				const [newResponse] = await tx
					.insert(response)
					.values({
						surveyId: surveyResult.id,
						respondentId: context.session?.user?.id ?? null,
						anonymousFingerprint: settings?.anonymous
							? (input.anonymousFingerprint ??
								generateFingerprint(input.metadata ?? {}))
							: null,
						metadata: input.metadata,
						status: "completed",
						completedAt: new Date(),
					})
					.returning();

				// Insert answers
				if (input.answers.length > 0) {
					await tx.insert(answer).values(
						input.answers.map((a) => ({
							responseId: newResponse.id,
							questionId: a.questionId,
							value: a.value,
						})),
					);
				}

				return newResponse;
			});

			return {
				success: true,
				responseId: result.id,
			};
		}),

	// ============================================
	// PROTECTED ENDPOINTS (for survey management)
	// ============================================

	// List responses for a survey (protected)
	list: protectedProcedure
		.input(
			z.object({
				filter: responseFilterSchema,
				pagination: paginationSchema.optional(),
			}),
		)
		.handler(async ({ context, input }) => {
			// Verify survey ownership
			const [surveyResult] = await db
				.select({ ownerId: survey.ownerId })
				.from(survey)
				.where(eq(survey.id, input.filter.surveyId));

			if (!surveyResult || surveyResult.ownerId !== context.session.user.id) {
				throw new Error("Survey not found or access denied");
			}

			const { page = 1, limit = 20 } = input.pagination ?? {};
			const conditions = [eq(response.surveyId, input.filter.surveyId)];

			if (input.filter.status) {
				conditions.push(eq(response.status, input.filter.status));
			}

			const [items, [{ total }]] = await Promise.all([
				db
					.select()
					.from(response)
					.where(and(...conditions))
					.orderBy(desc(response.completedAt))
					.limit(limit)
					.offset((page - 1) * limit),
				db
					.select({ total: count() })
					.from(response)
					.where(and(...conditions)),
			]);

			return {
				items,
				pagination: {
					page,
					limit,
					total,
					totalPages: Math.ceil(total / limit),
				},
			};
		}),

	// Get a single response with all answers (protected)
	getById: protectedProcedure
		.input(z.object({ id: z.number().int() }))
		.handler(async ({ context, input }) => {
			// Get response with survey ownership check
			const [responseResult] = await db
				.select({
					response: response,
					surveyOwnerId: survey.ownerId,
				})
				.from(response)
				.innerJoin(survey, eq(response.surveyId, survey.id))
				.where(eq(response.id, input.id));

			if (
				!responseResult ||
				responseResult.surveyOwnerId !== context.session.user.id
			) {
				throw new Error("Response not found or access denied");
			}

			// Get answers
			const answers = await db
				.select({
					answer: answer,
					question: question,
				})
				.from(answer)
				.innerJoin(question, eq(answer.questionId, question.id))
				.where(eq(answer.responseId, input.id));

			return {
				...responseResult.response,
				answers: answers.map((a) => ({
					...a.answer,
					question: a.question,
				})),
			};
		}),

	// Get response statistics for a survey (protected)
	getStats: protectedProcedure
		.input(z.object({ surveyId: z.number().int() }))
		.handler(async ({ context, input }) => {
			// Verify survey ownership
			const [surveyResult] = await db
				.select({ ownerId: survey.ownerId })
				.from(survey)
				.where(eq(survey.id, input.surveyId));

			if (!surveyResult || surveyResult.ownerId !== context.session.user.id) {
				throw new Error("Survey not found or access denied");
			}

			// Get total responses
			const [{ totalResponses }] = await db
				.select({ totalResponses: count() })
				.from(response)
				.where(
					and(
						eq(response.surveyId, input.surveyId),
						eq(response.status, "completed"),
					),
				);

			// Get average completion time
			const responses = await db
				.select({
					startedAt: response.startedAt,
					completedAt: response.completedAt,
				})
				.from(response)
				.where(
					and(
						eq(response.surveyId, input.surveyId),
						eq(response.status, "completed"),
					),
				);

			let avgCompletionTime = 0;
			if (responses.length > 0) {
				const totalTime = responses.reduce((acc, r) => {
					if (r.completedAt && r.startedAt) {
						return (
							acc +
							(r.completedAt.getTime() - r.startedAt.getTime()) / 1000
						);
					}
					return acc;
				}, 0);
				avgCompletionTime = Math.round(totalTime / responses.length);
			}

			return {
				totalResponses,
				avgCompletionTime,
			};
		}),

	// Delete a response (protected)
	delete: protectedProcedure
		.input(z.object({ id: z.number().int() }))
		.handler(async ({ context, input }) => {
			// Get response with survey ownership check
			const [responseResult] = await db
				.select({
					responseId: response.id,
					surveyOwnerId: survey.ownerId,
				})
				.from(response)
				.innerJoin(survey, eq(response.surveyId, survey.id))
				.where(eq(response.id, input.id));

			if (
				!responseResult ||
				responseResult.surveyOwnerId !== context.session.user.id
			) {
				throw new Error("Response not found or access denied");
			}

			await db.delete(response).where(eq(response.id, input.id));

			return { success: true, id: input.id };
		}),

	// Bulk delete responses (protected)
	bulkDelete: protectedProcedure
		.input(z.object({ ids: z.array(z.number().int()) }))
		.handler(async ({ context, input }) => {
			if (input.ids.length === 0) {
				return { success: true, deletedCount: 0 };
			}

			// Get all responses with survey ownership check
			const responsesWithSurvey = await db
				.select({
					responseId: response.id,
					surveyOwnerId: survey.ownerId,
				})
				.from(response)
				.innerJoin(survey, eq(response.surveyId, survey.id))
				.where(inArray(response.id, input.ids));

			const ownedIds = responsesWithSurvey
				.filter((r) => r.surveyOwnerId === context.session.user.id)
				.map((r) => r.responseId);

			if (ownedIds.length === 0) {
				return { success: true, deletedCount: 0 };
			}

			await db.delete(response).where(inArray(response.id, ownedIds));

			return { success: true, deletedCount: ownedIds.length };
		}),
};
