export const surveyRouter = {
	// List all surveys in active organization
	list: organizationProcedure.handler(async ({ context }) => {
		return await db
			.select()
			.from(survey)
			.where(eq(survey.organizationId, context.activeOrganization.id));
	}),

	// Get single survey
	get: organizationProcedure
		.input(z.object({ id: z.string() }))
		.handler(async ({ context, input }) => {
			const [result] = await db
				.select()
				.from(survey)
				.where(
					and(
						eq(survey.id, input.id),
						eq(survey.organizationId, context.activeOrganization.id)
					)
				);

			if (!result) {
				throw new ORPCError("NOT_FOUND", { message: "Survey not found" });
			}

			return result;
		}),

	// Create survey (admin+ only)
	create: adminProcedure
		.input(z.object({
			title: z.string().min(1),
			description: z.string().optional(),
			slug: z.string().min(1),
		}))
		.handler(async ({ context, input }) => {
			return await db.insert(survey).values({
				id: nanoid(),
				title: input.title,
				description: input.description,
				slug: input.slug,
				organizationId: context.activeOrganization.id,
				createdBy: context.session.user.id,
			}).returning();
		}),

	// Delete survey (owner only)
	delete: ownerProcedure
		.input(z.object({ id: z.string() }))
		.handler(async ({ context, input }) => {
			return await db
				.delete(survey)
				.where(
					and(
						eq(survey.id, input.id),
						eq(survey.organizationId, context.activeOrganization.id)
					)
				);
		}),
};
