import { createAccessControl } from "better-auth/plugins/access";
import { defaultStatements, adminAc, memberAc, ownerAc } from "better-auth/plugins/organization/access";

// Define custom survey-specific permissions
const customStatements = {
	...defaultStatements,
	survey: ["create", "read", "update", "delete", "publish"],
	response: ["read", "export"],
} as const;

export const ac = createAccessControl(customStatements);

// Define roles with merged permissions
export const member = ac.newRole({
	...memberAc.statements,
	survey: ["create", "read"],
	response: ["read"],
});

export const admin = ac.newRole({
	...adminAc.statements,
	survey: ["create", "read", "update", "delete", "publish"],
	response: ["read", "export"],
});

export const owner = ac.newRole({
	...ownerAc.statements,
	survey: ["create", "read", "update", "delete", "publish"],
	response: ["read", "export"],
});

export type AccessControl = typeof ac;
export type Statements = typeof customStatements;
