## 3. API Context and Procedures

### 3.1 Update Context

Update `/packages/api/src/context.ts`:

```typescript
// /packages/api/src/context.ts
import { auth } from "@orksys-survey/auth";
import type { Member, Organization } from "@orksys-survey/db/schema";
import type { NextRequest } from "next/server";

export interface OrganizationContext {
	session: NonNullable<Awaited<ReturnType<typeof auth.api.getSession>>>;
	activeOrganization: {
		id: string;
		name: string;
		slug: string;
	} | null;
	membership: {
		role: string;
	} | null;
}

export async function createContext(req: NextRequest) {
	const session = await auth.api.getSession({
		headers: req.headers,
	});

	if (!session) {
		return { session: null, activeOrganization: null, membership: null };
	}

	// Get active organization from session
	const activeOrgId = session.session.activeOrganizationId;

	if (!activeOrgId) {
		return { 
			session, 
			activeOrganization: null, 
			membership: null 
		};
	}

	// Fetch organization details
	const [org] = await db
		.select()
		.from(organization)
		.where(eq(organization.id, activeOrgId))
		.limit(1);

	// Get user's membership in the active organization
	const [membershipRecord] = await db
		.select()
		.from(member)
		.where(
			and(
				eq(member.userId, session.user.id),
				eq(member.organizationId, activeOrgId)
			)
		)
		.limit(1);

	return {
		session,
		activeOrganization: org ?? null,
		membership: membershipRecord ? { role: membershipRecord.role } : null,
	};
}

export type Context = Awaited<ReturnType<typeof createContext>>;
```

### 3.2 Update Procedure Definitions

