```typescript
// /packages/api/src/index.ts
import { ORPCError, os } from "@orpc/server";

import type { Context } from "./context";

export const o = os.$context<Context>();

export const publicProcedure = o;

// Auth-required middleware
const requireAuth = o.middleware(async ({ context, next }) => {
	if (!context.session?.user) {
		throw new ORPCError("UNAUTHORIZED");
	}
	return next({
		context: {
			session: context.session,
		},
	});
});

export const protectedProcedure = publicProcedure.use(requireAuth);

// Organization-aware middleware - requires active organization
const requireOrganization = protectedProcedure.middleware(async ({ context, next }) => {
	if (!context.activeOrganization) {
		throw new ORPCError("PRECONDITION_FAILED", {
			message: "No active organization selected",
		});
	}

	if (!context.membership) {
		throw new ORPCError("FORBIDDEN", {
			message: "You are not a member of the active organization",
		});
	}

	return next({
		context: {
			session: context.session,
			activeOrganization: context.activeOrganization,
			membership: context.membership,
		},
	});
});

// Procedure that requires an active organization
export const organizationProcedure = protectedProcedure.use(requireOrganization);

// Role-based middleware factories
export const requireRole = (allowedRoles: string[]) => 
	organizationProcedure.middleware(async ({ context, next }) => {
		const userRole = context.membership.role;

		if (!allowedRoles.includes(userRole)) {
			throw new ORPCError("FORBIDDEN", {
				message: `Requires one of roles: ${allowedRoles.join(", ")}`,
			});
		}

		return next({ context });
	});

// Owner-only procedure
export const ownerProcedure = organizationProcedure.use(requireRole(["owner"]));

// Admin+ procedure (includes owner)
export const adminProcedure = organizationProcedure.use(requireRole(["owner", "admin"]));
```

