## 5. Organization Switching Mechanism

### 5.1 Server-Side Organization API

Add to `/packages/api/src/routers/index.ts`:

```typescript
// Add to appRouter in /packages/api/src/routers/index.ts
import { protectedProcedure } from "../index";

export const appRouter = {
	// ... existing procedures ...

	// Organization management
	setActiveOrganization: protectedProcedure
		.input(z.object({ organizationId: z.string() }))
		.handler(async ({ context, input }) => {
			// Verify user is a member of this organization
			const [membership] = await db
				.select()
				.from(member)
				.where(
					and(
						eq(member.userId, context.session.user.id),
						eq(member.organizationId, input.organizationId)
					)
				)
				.limit(1);

			if (!membership) {
				throw new ORPCError("FORBIDDEN", {
					message: "You are not a member of this organization",
				});
			}

			// Update session's active organization
			await auth.api.setActiveOrganization({
				headers: context.headers,
				body: {
					organizationId: input.organizationId,
				},
			});

			return { success: true };
		}),

	// Get current user's organizations
	listMyOrganizations: protectedProcedure.handler(async ({ context }) => {
		const orgs = await db
			.select({
				id: organization.id,
				name: organization.name,
				slug: organization.slug,
				logo: organization.logo,
				role: member.role,
			})
			.from(organization)
			.innerJoin(member, eq(member.organizationId, organization.id))
			.where(eq(member.userId, context.session.user.id));

		return orgs;
	}),
};
```

