## 6. Middleware for Route Protection

### 6.1 Next.js Middleware

Create `/apps/web/src/middleware.ts`:

```typescript
// /apps/web/src/middleware.ts
import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";

// Public routes that don't require authentication
const publicRoutes = ["/", "/login", "/signup", "/accept-invitation"];

// Routes that require organization context
const organizationRequiredRoutes = ["/dashboard", "/surveys", "/settings"];

export async function middleware(request: NextRequest) {
	const { pathname } = request.nextUrl;

	// Allow public routes
	if (publicRoutes.some((route) => pathname.startsWith(route))) {
		return NextResponse.next();
	}

	// Survey runner routes (public for respondents)
	if (pathname.startsWith("/s/") || pathname.startsWith("/survey/")) {
		return NextResponse.next();
	}

	// For protected routes, the auth check will be handled by layout components
	// or individual pages using authClient.useSession()

	return NextResponse.next();
}

export const config = {
	matcher: ["/((?!api|_next/static|_next/image|favicon.ico).*)"],
};
```

